import {solve,parseFormula,number,examples} from './engine.mjs';
import {render3D,defaultCamera} from './plot3d.mjs';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=4)=>Math.abs(n)<.5*10**-d?(0).toFixed(d):n.toFixed(d), sub=s=>esc(s).replace(/(\d+(?:\.\d+)?)/g,'<sub>$1</sub>');
const colors=['#68818e','#8798a1','#576e85','#087f78','#386bb8','#b47224','#9a55a6','#ae555d','#387c55','#755bc5'];
let model=structuredClone(examples.SrTiO3),result,selected,selectionName='Interior',own=false,dirty=false;
let axes=['Sr','Ti','O'],view='2d',camera={...defaultCamera},projection3D;
function color(q){return colors[result.constraints.indexOf(q)%colors.length];}
function message(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(message.timer);message.timer=setTimeout(()=>$('toast').style.display='none',2800);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setDirty(){dirty=true;$('dirty').hidden=false;if(result){$('region-status').textContent='Inputs changed · recalculate';$('region-status').classList.add('warning');}for(const id of ['export-point','export-vertices','export-svg'])$(id).disabled=true;}
function referenceFields(refs=model.refs){let elements;try{elements=Object.keys(parseFormula($('target-formula').value));}catch{return;}if(elements.length!==3)return;
  if(axes.some(e=>!elements.includes(e)))axes=[...elements];
  fillAxes(elements);
  $('reference-inputs').innerHTML=elements.map(e=>`<label>${e}<input data-reference="${e}" aria-label="${e} reference energy" type="number" step="any" value="${esc(refs[e]??'')}" placeholder="μ⁰"></label>`).join('');
}
function fillAxes(elements){for(const [i,id]of ['axis-x','axis-y','axis-z'].entries()){$(id).innerHTML=elements.map(e=>`<option value="${e}">Δμ${e}</option>`).join('');$(id).value=axes[i];}}
function validatedCamera(value){const c={...defaultCamera};for(const [key,min,max]of [['azimuth',-180,180],['elevation',-85,85],['zoom',.5,2]])if(typeof value?.[key]==='number'&&Number.isFinite(value[key]))c[key]=Math.max(min,Math.min(max,value[key]));if(typeof value?.showHost==='boolean')c.showHost=value.showHost;return c;}
function syncCamera(){for(const k of ['azimuth','elevation','zoom'])$(k).value=camera[k];$('azimuth-value').textContent=`${Math.round(camera.azimuth)}°`;$('elevation-value').textContent=`${Math.round(camera.elevation)}°`;$('zoom-value').textContent=`${camera.zoom.toFixed(2)}×`;$('show-host').checked=camera.showHost;}
function syncView(){$('view-2d').setAttribute('aria-pressed',String(view==='2d'));$('view-3d').setAttribute('aria-pressed',String(view==='3d'));$('camera-controls').hidden=view!=='3d';$('three-d-note').hidden=view!=='3d';$('plot').classList.toggle('three-d',view==='3d');$('axis-help').textContent=view==='2d'?'2D shows X versus Y. Z is calculated from the host equality. Selecting an assigned element swaps the two axes.':'3D shows all three assigned potentials. Z still follows the host equality; the allowed region is planar. Selecting an assigned element swaps the two axes.';$('plot-instruction').textContent=view==='3d'?'Drag to rotate · click to select':'Click inside the polygon to inspect a point';syncCamera();}
function phaseRow(p,index){return `<div class="phase-row" data-row="${index}"><div class="phase-main"><input type="checkbox" class="enabled" aria-label="Include phase ${index+1}" ${p.enabled!==false?'checked':''}><input class="formula" aria-label="Phase ${index+1} formula" value="${esc(p.formula)}" placeholder="TiO2" required><input class="energy" type="number" step="any" aria-label="Phase ${index+1} energy" value="${esc(p.energy)}" required><button type="button" class="remove" aria-label="Remove phase ${index+1}">×</button></div><div class="phase-sub"><select class="basis" aria-label="Phase ${index+1} energy basis">${['formula','atom','cell'].map(b=>`<option value="${b}" ${p.basis===b?'selected':''}>eV / ${b}</option>`).join('')}</select><input class="units" type="number" step="any" min="0.000001" aria-label="Phase ${index+1} formula units per cell" value="${esc(p.units??1)}" ${p.basis==='cell'?'':'hidden'}><span ${p.basis==='cell'?'':'hidden'}>f.u./cell</span></div></div>`;}
function populate(m){model=structuredClone(m);$('target-formula').value=m.target.formula;$('target-energy').value=m.target.energy;$('mode').value=m.mode;$('target-basis').value=m.target.basis||'formula';$('target-units').value=m.target.units??1;referenceFields(m.refs||{});const elements=Object.keys(parseFormula(m.target.formula)),z=m.eliminated||elements[2];axes=m.axes?[...m.axes]:[...elements.filter(e=>e!==z),z];fillAxes(elements);$('phases').innerHTML=m.phases.map(phaseRow).join('');basisVisibility();$('references').open=m.mode==='total';}
function basisVisibility(){$('target-units-label').hidden=$('target-basis').value!=='cell';for(const row of document.querySelectorAll('.phase-row')){const cell=row.querySelector('.basis').value==='cell';row.querySelector('.units').hidden=!cell;row.querySelector('.phase-sub span').hidden=!cell;const disabled=!row.querySelector('.enabled').checked;row.querySelector('.formula').required=!disabled;row.querySelector('.energy').required=!disabled;}}
function readInputs(){return {mode:$('mode').value,eliminated:axes[2],axes:[...axes],refs:Object.fromEntries([...document.querySelectorAll('[data-reference]')].map(el=>[el.dataset.reference,el.value])),target:{formula:$('target-formula').value,energy:$('target-energy').value,basis:$('target-basis').value,units:$('target-units').value},phases:[...document.querySelectorAll('.phase-row')].map(row=>({formula:row.querySelector('.formula').value,energy:row.querySelector('.energy').value,basis:row.querySelector('.basis').value,units:row.querySelector('.units').value,enabled:row.querySelector('.enabled').checked}))};}
function equation(counts){return Object.entries(counts).filter(([,v])=>v!==0).map(([e,v])=>`${v===1?'':fmt(v,3).replace(/\.?0+$/,'')}Δμ${e}`).join(' + ');}
function reduced(q){return `${fmt(q.A,4)} x ${q.B<0?'−':'+'} ${fmt(Math.abs(q.B),4)} y ≤ ${fmt(q.C,4)}`;}
function calculate(candidate=readInputs()){try{const next=solve(candidate);model=structuredClone(candidate);result=next;dirty=false;$('dirty').hidden=true;$('input-error').textContent='';selected=result.vertices.length?result.vertices.reduce((p,q)=>[p[0]+q[0]/result.vertices.length,p[1]+q[1]/result.vertices.length],[0,0]):null;selectionName=result.dimension===2?'Interior':'Equilibrium';render();return true;}catch(e){$('input-error').textContent=e.message;setDirty();return false;}}
function provenance(){$('provenance').classList.toggle('own',own);$('provenance').querySelector('strong').textContent=own?'User-supplied energies':'Illustrative example';$('provenance').querySelector('span').textContent=own?'Results are conditional on your energy references and included competing phases.':'These energies demonstrate the method. Replace them with a consistent DFT dataset before research use.';$('acknowledge').checked=own;}
function render(){const r=result;$('plot-title').innerHTML=`${sub(model.target.formula)} stability region`;$('host-equation').textContent=`${equation(r.composition)} = ${fmt(r.h,4)} eV / formula`;
  $('region-status').textContent=r.dimension===2?`${r.vertices.length} vertices · stable region`:r.dimension===-1?'No stable region':r.dimension===1?'Line equilibrium only':'Point equilibrium only';$('region-status').classList.toggle('warning',r.dimension!==2);
  $('plot-message').textContent=r.dimension===-1?'No chemical potentials satisfy every enabled constraint. Check units, reference energies, and whether the target is unstable against the included phases.':r.dimension<2?'The feasible set has zero area. It represents marginal coexistence, without a finite stability window.':'';
  $('constraint-count').textContent=`${r.constraints.length} constraints · x = Δμ${r.x}, y = Δμ${r.y}`;
  $('constraints').innerHTML=`<table><thead><tr><th>Boundary</th><th>Original inequality</th><th>After eliminating ${r.z}</th><th>Touches region</th></tr></thead><tbody>${r.constraints.map(q=>`<tr><td><i class="boundary-color" style="background:${color(q)}"></i>${esc(q.label)}</td><td class="numeric">${esc(equation(q.counts))} ≤ ${fmt(q.enthalpy,4)}</td><td class="numeric">${esc(reduced(q))}</td><td>${r.vertices.some(p=>r.active(p).includes(q))?'Yes':'No'}</td></tr>`).join('')}</tbody></table>`;
  $('point-x-label').firstChild.textContent=`Δμ${r.x} (eV/atom)`;$('point-y-label').firstChild.textContent=`Δμ${r.y} (eV/atom)`;
  for(const id of ['export-point','export-vertices','choose-point','center-point'])$(id).disabled=!selected;$('export-svg').disabled=false;renderSelection();
}
function renderSelection(){const r=result;$('selection-name').textContent=selected?selectionName:'Unavailable';$('point-error').textContent='';
  const mu=selected?r.chemicalPotentials(selected):{};
  $('potentials').innerHTML=r.elements.map(e=>{const ref=model.refs?.[e],hasRef=ref!==''&&ref!==undefined&&ref!==null&&String(ref).trim()!==''&&Number.isFinite(Number(ref));return `<div class="potential ${e===r.z?'dependent':''}"><div class="label">Δμ${esc(e)} ${e===r.z?'· dependent':''}</div><div class="value">${selected?fmt(mu[e]):'—'}</div><div class="unit">eV / atom</div><div class="absolute">${selected&&hasRef?`μ${esc(e)} = ${fmt(mu[e]+Number(ref))}`:'Absolute μ needs μ⁰'}</div></div>`;}).join('');
  $('point-x').value=selected?fmt(selected[0],8):'';$('point-y').value=selected?fmt(selected[1],8):'';
  const co=selected?r.active(selected).map(q=>q.label):[];$('coexistence').textContent=selected?(co.length?`Active boundaries: ${co.join(' · ')}`:'Interior condition: no competing-phase boundary is active.'):'No valid condition available.';
  $('vertices').innerHTML=r.vertices.length?`<table><thead><tr><th>Point</th>${r.elements.map(e=>`<th>Δμ${esc(e)} (eV/atom)</th>`).join('')}<th>Active boundaries</th></tr></thead><tbody>${r.vertices.map((p,i)=>{const m=r.chemicalPotentials(p);return `<tr><td><button class="vertex-button ${selectionName===`V${i+1}`?'selected':''}" data-vertex="${i}">V${i+1}</button></td>${r.elements.map(e=>`<td class="numeric">${fmt(m[e],6)}</td>`).join('')}<td>${esc(r.active(p).map(q=>q.label).join(' · '))}</td></tr>`;}).join('')}</tbody></table>`:'<p class="hint">No feasible vertices for this phase set.</p>';
  drawPlot();
}
let plotMap;
function drawPlot(){
  if(view==='3d'){const output=render3D(result,{camera,selected,own,formula:model.target.formula,color});projection3D=output.projection;$('plot').innerHTML=output.svg;return;}
  const r=result,W=860,H=490,L=78,R=35,T=32,B=68;
  let xmin,xmax,ymin,ymax;if(r.vertices.length){xmin=Math.min(...r.vertices.map(p=>p[0]));xmax=Math.max(...r.vertices.map(p=>p[0]));ymin=Math.min(...r.vertices.map(p=>p[1]));ymax=Math.max(...r.vertices.map(p=>p[1]));}else{xmin=Math.min(-1,r.h/r.composition[r.x]);xmax=0;ymin=Math.min(-1,r.h/r.composition[r.y]);ymax=0;}
  const dx=Math.max(xmax-xmin,.5),dy=Math.max(ymax-ymin,.5);xmin-=dx*.16;xmax+=dx*.16;ymin-=dy*.16;ymax+=dy*.16;
  const sx=x=>L+(x-xmin)/(xmax-xmin)*(W-L-R),sy=y=>H-B-(y-ymin)/(ymax-ymin)*(H-T-B);plotMap={W,H,L,R,T,B,xmin,xmax,ymin,ymax,sx,sy};
  let svg=`<svg id="diagram" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Chemical-potential stability diagram for ${esc(model.target.formula)}. Use the vertex table or numeric point fields for keyboard selection."><title>${esc(model.target.formula)} chemical-potential stability</title><desc>${own?'User-supplied':'Illustrative'} energies. ${r.vertices.length} feasible vertices. Δμ in eV per atom.</desc><rect width="${W}" height="${H}" fill="white"/><defs><clipPath id="plot-clip"><rect x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}"/></clipPath></defs>`;
  for(let i=0;i<=5;i++){const x=xmin+(xmax-xmin)*i/5,y=ymin+(ymax-ymin)*i/5;svg+=`<path d="M${sx(x)} ${T}V${H-B} M${L} ${sy(y)}H${W-R}" stroke="#e7eef2" fill="none"/><text x="${sx(x)}" y="${H-B+24}" text-anchor="middle" fill="#607987" font-family="monospace" font-size="13">${fmt(x,2)}</text><text x="${L-13}" y="${sy(y)+4}" text-anchor="end" fill="#607987" font-family="monospace" font-size="13">${fmt(y,2)}</text>`;}
  svg+=`<path d="M${L} ${T}V${H-B}H${W-R}" stroke="#9bb0bb" fill="none"/><g clip-path="url(#plot-clip)">`;
  for(const q of r.constraints){const pts=[];if(Math.abs(q.B)>1e-12)for(const x of [xmin,xmax]){const y=(q.C-q.A*x)/q.B;if(y>=ymin-1e-8&&y<=ymax+1e-8)pts.push([x,y]);}if(Math.abs(q.A)>1e-12)for(const y of [ymin,ymax]){const x=(q.C-q.B*y)/q.A;if(x>=xmin-1e-8&&x<=xmax+1e-8)pts.push([x,y]);}if(pts.length>=2)svg+=`<line x1="${sx(pts[0][0])}" y1="${sy(pts[0][1])}" x2="${sx(pts.at(-1)[0])}" y2="${sy(pts.at(-1)[1])}" stroke="${color(q)}" stroke-width="1.3" stroke-dasharray="6 5" opacity=".55"/>`;}
  if(r.vertices.length>=3)svg+=`<polygon points="${r.vertices.map(p=>`${sx(p[0])},${sy(p[1])}`).join(' ')}" fill="#b9e9dd" fill-opacity=".65" stroke="#087f78" stroke-width="2.2"/>`;
  if(r.vertices.length===2)svg+=`<line x1="${sx(r.vertices[0][0])}" y1="${sy(r.vertices[0][1])}" x2="${sx(r.vertices[1][0])}" y2="${sy(r.vertices[1][1])}" stroke="#087f78" stroke-width="3"/>`;
  svg+='</g>';
  if(r.vertices.length>2){const center=r.vertices.reduce((p,q)=>[p[0]+sx(q[0])/r.vertices.length,p[1]+sy(q[1])/r.vertices.length],[0,0]);r.vertices.forEach((p,i)=>{const q=r.vertices[(i+1)%r.vertices.length],mid=[(p[0]+q[0])/2,(p[1]+q[1])/2],active=r.active(mid),xp=sx(mid[0]),yp=sy(mid[1]),norm=Math.hypot(xp-center[0],yp-center[1])||1;const lx=xp+17*(xp-center[0])/norm,ly=yp+17*(yp-center[1])/norm;svg+=`<text x="${lx}" y="${ly}" text-anchor="middle" dominant-baseline="middle" fill="${active.length?color(active[0]):'#087f78'}" font-size="14" font-family="system-ui" font-weight="600" stroke="white" stroke-width="5" paint-order="stroke">${esc(active.map(q=>q.label.replace(' elemental limit','')).join(' / '))}</text>`;});}
  r.vertices.forEach((p,i)=>{svg+=`<g data-vertex="${i}" style="cursor:pointer"><circle cx="${sx(p[0])}" cy="${sy(p[1])}" r="13" fill="transparent"/><circle cx="${sx(p[0])}" cy="${sy(p[1])}" r="4.5" fill="white" stroke="#087f78" stroke-width="2"/><text x="${sx(p[0])+8}" y="${sy(p[1])-10}" fill="#193f4b" font-size="12" font-weight="600" font-family="system-ui" stroke="white" stroke-width="3" paint-order="stroke">V${i+1}</text></g>`;});
  if(selected)svg+=`<g pointer-events="none"><path d="M${sx(selected[0])-12} ${sy(selected[1])}h24 M${sx(selected[0])} ${sy(selected[1])-12}v24" stroke="#c25b26"/><circle cx="${sx(selected[0])}" cy="${sy(selected[1])}" r="5" fill="#c25b26" stroke="white" stroke-width="2"/></g>`;
  if(!r.vertices.length)svg+=`<text x="${W/2}" y="${H/2}" text-anchor="middle" fill="#a45a27" font-size="21" font-family="system-ui">No feasible stability region</text>`;
  svg+=`<text x="${(L+W-R)/2}" y="${H-15}" text-anchor="middle" font-family="system-ui" font-size="16" fill="#334e5c">Δμ${r.x} (eV / atom)</text><text transform="translate(21 ${(T+H-B)/2}) rotate(-90)" text-anchor="middle" font-family="system-ui" font-size="16" fill="#334e5c">Δμ${r.y} (eV / atom)</text><text x="${W-R}" y="17" text-anchor="end" fill="#7a8e98" font-family="system-ui" font-size="12">${own?'USER-SUPPLIED ENERGIES':'ILLUSTRATIVE ENERGIES'}</text></svg>`;$('plot').innerHTML=svg;
}
function choose(p,name='Custom point'){if(dirty){$('point-error').textContent='Calculate the changed inputs before choosing a condition.';return false;}if(!p.every(Number.isFinite)||!result.feasible(p)){$('point-error').textContent='That point is outside the allowed region. Choose a vertex or a point inside the polygon.';return false;}selected=[...p];selectionName=name;renderSelection();return true;}
function csv(points){const fields=['condition','target','energy_provenance',...result.elements.map(e=>`delta_mu_${e}_eV_per_atom`),...result.elements.map(e=>`mu0_${e}_eV_per_atom`),...result.elements.map(e=>`mu_${e}_eV_per_atom`),'active_boundaries'];const rows=points.map(({p,name})=>{const m=result.chemicalPotentials(p);return [name,model.target.formula,own?'user-supplied':'illustrative',...result.elements.map(e=>m[e]),...result.elements.map(e=>model.refs?.[e]??''),...result.elements.map(e=>{const v=model.refs?.[e];return v!==''&&v!=null&&String(v).trim()!==''&&Number.isFinite(Number(v))?m[e]+Number(v):'';}),result.active(p).map(q=>q.label).join('; ')];});return [fields,...rows].map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');}
$('system-form').addEventListener('submit',e=>{e.preventDefault();calculate();});$('system-form').addEventListener('input',setDirty);
$('system-form').addEventListener('change',e=>{basisVisibility();if(e.target.id==='mode'){$('references').open=$('mode').value==='total';}setDirty();});
$('target-formula').addEventListener('change',()=>{const refs=Object.fromEntries([...document.querySelectorAll('[data-reference]')].map(e=>[e.dataset.reference,e.value]));referenceFields(refs);});
$('add-phase').onclick=()=>{if(document.querySelectorAll('.phase-row').length>=150){message('Maximum 150 phases.');return;}$('phases').insertAdjacentHTML('beforeend',phaseRow({formula:'',energy:'',basis:'formula',units:1,enabled:true},Math.max(-1,...[...document.querySelectorAll('.phase-row')].map(r=>Number(r.dataset.row)))+1));setDirty();};
$('phases').addEventListener('click',e=>{if(e.target.closest('.remove')){e.target.closest('.phase-row').remove();setDirty();}});
$('example').onchange=()=>{own=false;provenance();populate(examples[$('example').value]);calculate();};$('acknowledge').onchange=()=>{own=$('acknowledge').checked;provenance();if(result)drawPlot();};
$('vertices').addEventListener('click',e=>{const b=e.target.closest('[data-vertex]');if(b)choose(result.vertices[Number(b.dataset.vertex)],`V${Number(b.dataset.vertex)+1}`);});
$('plot').addEventListener('click',e=>{if(discardClick){discardClick=false;return;}const vertex=e.target.closest('[data-vertex]');if(vertex){choose(result.vertices[Number(vertex.dataset.vertex)],`V${Number(vertex.dataset.vertex)+1}`);return;}if(!result.vertices.length)return;const svg=$('diagram'),point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const p=point.matrixTransform(svg.getScreenCTM().inverse());if(view==='3d'){const picked=projection3D.unproject([p.x,p.y]);if(!picked){$('point-error').textContent='This view is edge-on. Rotate the plane or choose a table vertex.';return;}choose(picked);return;}const m=plotMap;if(p.x<m.L||p.x>m.W-m.R||p.y<m.T||p.y>m.H-m.B)return;choose([m.xmin+(p.x-m.L)/(m.W-m.L-m.R)*(m.xmax-m.xmin),m.ymin+(m.H-m.B-p.y)/(m.H-m.T-m.B)*(m.ymax-m.ymin)]);});
$('choose-point').onclick=()=>{try{choose([number($('point-x').value,'x'),number($('point-y').value,'y')]);}catch(e){$('point-error').textContent=e.message;}};$('center-point').onclick=()=>choose(result.vertices.reduce((p,q)=>[p[0]+q[0]/result.vertices.length,p[1]+q[1]/result.vertices.length],[0,0]),result.dimension===2?'Interior':'Equilibrium');
$('export-point').onclick=()=>download('chemical-potential-condition.csv',csv([{p:selected,name:selectionName}]),'text/csv');$('export-vertices').onclick=()=>download('chemical-potential-vertices.csv',csv(result.vertices.map((p,i)=>({p,name:`V${i+1}`}))),'text/csv');$('export-svg').onclick=()=>download('chemical-potential-diagram.svg',new XMLSerializer().serializeToString($('diagram')),'image/svg+xml');
$('save').onclick=()=>{try{const m=readInputs();solve(m);download('chemical-potential-session.json',JSON.stringify({schemaVersion:1,ownEnergies:own,model:m,view,camera,selected:dirty?null:selected},null,2),'application/json');message('Session saved.');}catch(e){message(e.message);}};
$('load').onclick=()=>$('session-file').click();$('session-file').onchange=async()=>{try{const file=$('session-file').files[0];if(!file)return;if(file.size>500000)throw Error('Session file exceeds 500 KB.');const data=JSON.parse(await file.text());if(data.schemaVersion!==1||!data.model)throw Error('This is not a Chemical Potential Lab session.');solve(data.model);if(data.selected!=null&&(!Array.isArray(data.selected)||data.selected.length!==2||!data.selected.every(Number.isFinite)))throw Error('Invalid saved point.');populate(data.model);view=data.view==='3d'?'3d':'2d';camera=validatedCamera(data.camera);syncView();own=data.ownEnergies===true;provenance();calculate();if(data.selected)choose(data.selected);message('Session loaded.');}catch(e){message(`Could not open session: ${e.message}`);}finally{$('session-file').value='';}};
for(const [i,id]of ['axis-x','axis-y','axis-z'].entries())$(id).onchange=()=>{
  const next=$(id).value,previous=axes[i],other=axes.indexOf(next),m=selected&&result?result.chemicalPotentials(selected):null;
  if(other!==i)axes[other]=previous;axes[i]=next;fillAxes([...axes]);
  if(dirty){setDirty();return;}if(calculate()&&m)choose([m[result.x],m[result.y]],'Preserved condition');
};
for(const mode of ['2d','3d'])$(`view-${mode}`).onclick=()=>{view=mode;syncView();drawPlot();};
for(const key of ['azimuth','elevation','zoom'])$(key).oninput=()=>{camera[key]=Number($(key).value);syncCamera();drawPlot();};
$('show-host').onchange=()=>{camera.showHost=$('show-host').checked;drawPlot();};
$('reset-camera').onclick=()=>{camera={...defaultCamera};syncCamera();drawPlot();};
let drag=null,discardClick=false;
$('plot').addEventListener('pointerdown',e=>{discardClick=false;if(view!=='3d'||e.button!==0||drag)return;drag={vertex:e.target.closest('[data-vertex]')?.dataset.vertex,id:e.pointerId,x:e.clientX,y:e.clientY,azimuth:camera.azimuth,elevation:camera.elevation,moved:false};$('plot').setPointerCapture(e.pointerId);});
$('plot').addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)<4&&!drag.moved)return;drag.moved=true;camera.azimuth=((drag.azimuth+dx*.5+540)%360)-180;camera.elevation=Math.max(-85,Math.min(85,drag.elevation-dy*.4));syncCamera();drawPlot();});
$('plot').addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.id)return;discardClick=drag.moved;const vertex=drag.vertex;if(!drag.moved&&vertex!==undefined){choose(result.vertices[Number(vertex)],`V${Number(vertex)+1}`);discardClick=true;}drag=null;if($('plot').hasPointerCapture(e.pointerId))$('plot').releasePointerCapture(e.pointerId);});
$('plot').addEventListener('pointercancel',()=>{drag=null;discardClick=false;});
$('plot').addEventListener('keydown',e=>{if(view!=='3d')return;const delta={ArrowLeft:[-5,0],ArrowRight:[5,0],ArrowUp:[0,5],ArrowDown:[0,-5]}[e.key];if(delta){e.preventDefault();camera.azimuth=((camera.azimuth+delta[0]+540)%360)-180;camera.elevation=Math.max(-85,Math.min(85,camera.elevation+delta[1]));}else if(['+','=','-','_'].includes(e.key)){e.preventDefault();camera.zoom=Math.max(.5,Math.min(2,camera.zoom+(['-','_'].includes(e.key)?-.1:.1)));}else return;syncCamera();drawPlot();});
populate(model);syncView();calculate();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_stability_diagram',title:'Read stability results',description:'Read the current calculated stability region and selected chemical potentials. Reports whether inputs have changed.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({dirty,view,axes:{x:result.x,y:result.y,z:result.z},target:model.target.formula,dimension:result.dimension,vertices:result.vertices.map(p=>result.chemicalPotentials(p)),selected:selected?result.chemicalPotentials(selected):null})},{name:'select_chemical_potential_point',title:'Select a chemical-potential condition',description:'Select a feasible point in the current diagram using the same validation as the numeric point controls.',inputSchema:{type:'object',properties:{x:{type:'number'},y:{type:'number'}},required:['x','y'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.x!=='number'||typeof input.y!=='number'||!choose([input.x,input.y]))throw Error('Point is invalid, outside the region, or inputs require recalculation.');return {selected:result.chemicalPotentials(selected)};}}])try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
